import { useState } from 'react'
import { pruneSelectionForAssignment } from '../pruneSelection'
import { SelectionHandle } from './useSelection'
import { DriveAssignmentsHandle } from './useDriveAssignments'
import { LocalFileGroup, DriveAssignment, SelectionItem } from '../types'

export interface DrivePickerHandle {
  opened: boolean
  pickOne: (target: SelectionItem) => void
  pickSelection: () => void
  apply: (folder: DriveAssignment) => void
  close: () => void
}

// One or more targets for the currently open folder picker: a single-item
// array for a per-row badge click (pickOne), or the pruned multi-selection
// for the toolbar batch action (pickSelection) — either way, the picked
// folder applies to every target here.
export function useDrivePicker(tree: LocalFileGroup | null, selection: SelectionHandle, assignments: DriveAssignmentsHandle): DrivePickerHandle {
  const [targets, setTargets] = useState<SelectionItem[] | null>(null)

  const pickOne = (target: SelectionItem) => setTargets([target])

  const pickSelection = () => {
    if (!tree) return
    setTargets(pruneSelectionForAssignment(tree, selection.items))
  }

  const apply = (folder: DriveAssignment) => {
    for (const target of targets ?? []) {
      if (target.type === 'group') assignments.setGroupAssignment(target.key, folder)
      else assignments.setFileOverride(target.path, folder)
    }
    setTargets(null)
  }

  const close = () => setTargets(null)

  return { opened: targets !== null, pickOne, pickSelection, apply, close }
}

import { useState, useCallback } from 'react'
import { PickFolder, ScanLocalRoot } from '../../../../wailsjs/go/main/App'
import { LocalFile, LocalFileGroup } from '../types'

// Flat, ordered list of every file in the tree (a group's own files, then
// its subgroups' files, recursively). Shared by the upload worker (order to
// process files in), the upload modal's per-group rollup counts, and the
// "every file in this group is done" check driving the Open-in-Drive link —
// one traversal so they can't drift out of sync on how they handle nesting.
export function flattenFiles(group: LocalFileGroup): LocalFile[] {
  return [...group.files, ...group.subgroups.flatMap(flattenFiles)]
}

export interface FileTreeHandle {
  root: string | null
  tree: LocalFileGroup | null
  loading: boolean
  error: string | null
  // Resolves to whether a folder was actually picked (false if the user
  // cancelled the dialog), so callers know when a fresh root replaced the
  // previous one and any per-root state (e.g. the upload queue) should reset.
  pickRoot: () => Promise<boolean>
}

export function useFileTree(): FileTreeHandle {
  const [root, setRoot] = useState<string | null>(null)
  const [tree, setTree] = useState<LocalFileGroup | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const pickRoot = useCallback(async () => {
    const folder = await PickFolder('Choose Root Folder')
    if (!folder) return false

    setRoot(folder)
    setLoading(true)
    setError(null)
    try {
      setTree(await ScanLocalRoot(folder))
    } catch (e) {
      setTree(null)
      setError(String(e))
    } finally {
      setLoading(false)
    }
    return true
  }, [])

  return { root, tree, loading, error, pickRoot }
}

import { useState, useCallback } from 'react'
import { LocalFileGroup, DriveAssignment } from '../types'

export interface DriveAssignmentsHandle {
  groupAssignments: Map<string, DriveAssignment>
  fileOverrides: Map<string, DriveAssignment>
  setGroupAssignment: (groupKey: string, assignment: DriveAssignment) => void
  clearGroupAssignment: (groupKey: string) => void
  setFileOverride: (filePath: string, assignment: DriveAssignment) => void
  clearFileOverride: (filePath: string) => void
}

// Tracks Drive folder assignments made directly on a subfolder group or on
// an individual file (a file-level assignment overrides its group's).
// Resolving the *effective* assignment for a given group/file (own, else
// inherited from the nearest ancestor group, else none) is the caller's
// job, since only the caller knows the tree structure to walk.
export function useDriveAssignments(): DriveAssignmentsHandle {
  const [groupAssignments, setGroupAssignments] = useState<Map<string, DriveAssignment>>(new Map())
  const [fileOverrides, setFileOverrides] = useState<Map<string, DriveAssignment>>(new Map())

  const setGroupAssignment = useCallback((groupKey: string, assignment: DriveAssignment) => {
    setGroupAssignments(prev => new Map(prev).set(groupKey, assignment))
  }, [])

  const clearGroupAssignment = useCallback((groupKey: string) => {
    setGroupAssignments(prev => {
      const next = new Map(prev)
      next.delete(groupKey)
      return next
    })
  }, [])

  const setFileOverride = useCallback((filePath: string, assignment: DriveAssignment) => {
    setFileOverrides(prev => new Map(prev).set(filePath, assignment))
  }, [])

  const clearFileOverride = useCallback((filePath: string) => {
    setFileOverrides(prev => {
      const next = new Map(prev)
      next.delete(filePath)
      return next
    })
  }, [])

  return { groupAssignments, fileOverrides, setGroupAssignment, clearGroupAssignment, setFileOverride, clearFileOverride }
}

// Effective Drive assignment for every file in the tree: its own override,
// else the nearest ancestor group's assignment, else null. Mirrors the
// inheritance walk GroupNode/FileList do inline during render (same
// groupKey scheme: joined by '/', rooted at each top-level subgroup's own
// name), but usable outside a render tree — e.g. to check whether every
// file is ready to upload, or to build an upload job list.
export function resolveEffectiveAssignments(
  tree: LocalFileGroup,
  { groupAssignments, fileOverrides }: Pick<DriveAssignmentsHandle, 'groupAssignments' | 'fileOverrides'>
): Map<string, DriveAssignment | null> {
  const result = new Map<string, DriveAssignment | null>()

  const walk = (group: LocalFileGroup, groupKey: string | null, inherited: DriveAssignment | null) => {
    const effective = (groupKey !== null ? groupAssignments.get(groupKey) : undefined) ?? inherited
    for (const file of group.files) {
      result.set(file.path, fileOverrides.get(file.path) ?? effective)
    }
    for (const sub of group.subgroups) {
      walk(sub, groupKey !== null ? `${groupKey}/${sub.name}` : sub.name, effective)
    }
  }
  walk(tree, null, null)

  return result
}

import { useState } from 'react'
import { flattenFiles } from './useFileTree'
import { resolveEffectiveAssignments, DriveAssignmentsHandle } from './useDriveAssignments'
import { InclusionHandle } from './useInclusion'
import { LocalFileGroup } from '../types'
import * as uploadQueue from '../uploadQueue'

export interface UploadFlowHandle {
  started: boolean
  uploadModalOpen: boolean
  readyToUpload: boolean
  startUpload: () => void
  closeUploadModal: () => void
  reset: () => void
}

// Once Upload All is clicked, the tree locks for the rest of this tree's
// session — the upload starts immediately, so there's no "in progress but
// not locked yet" window to account for. Retrying failed files happens
// inside the upload modal, not from here, so `started` never goes back to
// false except via reset (a fresh root pick).
export function useUploadFlow(tree: LocalFileGroup | null, inclusion: InclusionHandle, assignments: DriveAssignmentsHandle): UploadFlowHandle {
  const [uploadModalOpen, setUploadModalOpen] = useState(false)
  const [started, setStarted] = useState(false)

  const allFiles = tree ? flattenFiles(tree) : []
  const selectedFiles = allFiles.filter(f => inclusion.isFileSelected(f.path))
  const effectiveAssignments = tree ? resolveEffectiveAssignments(tree, assignments) : null
  const readyToUpload = selectedFiles.length > 0 && selectedFiles.every(f => effectiveAssignments!.get(f.path) != null)

  const startUpload = () => {
    if (!tree || !effectiveAssignments) return
    uploadQueue.start(selectedFiles.map(f => {
      const assignment = effectiveAssignments.get(f.path)
      // Upload All is disabled until readyToUpload is true, so every file
      // should resolve here — this is a defensive check against that
      // guard and this walk drifting out of sync, not an expected path.
      if (!assignment) throw new Error(`No Drive folder assigned for "${f.path}"`)
      return { path: f.path, folderId: assignment.driveFolderId, name: f.name }
    }))
    setStarted(true)
    setUploadModalOpen(true)
  }

  const closeUploadModal = () => setUploadModalOpen(false)

  // A new root discards the old tree's upload-queue state along with it —
  // picking a new root is the only way out of the read-only lock.
  const reset = () => {
    uploadQueue.reset()
    setStarted(false)
  }

  return { started, uploadModalOpen, readyToUpload, startUpload, closeUploadModal, reset }
}

import { useState, useCallback, useEffect } from 'react'
import { flattenFiles } from './useFileTree'
import { LocalFileGroup } from '../types'

export type GroupSelectionState = 'checked' | 'unchecked' | 'indeterminate'

export interface InclusionHandle {
  isFileSelected: (path: string) => boolean
  getGroupState: (group: LocalFileGroup) => GroupSelectionState
  toggleFile: (path: string) => void
  toggleGroup: (group: LocalFileGroup) => void
  selectAll: () => void
  selectNone: () => void
}

// Tracks which files are excluded from the upload, keyed by path. A
// subfolder's checkbox state is derived from its descendant files rather
// than stored separately, so the "fully selected/unselected collapses all
// the way up the tree" behavior falls out of the derivation for free
// instead of needing explicit upward-propagation bookkeeping.
export function useInclusion(tree: LocalFileGroup | null): InclusionHandle {
  const [deselected, setDeselected] = useState<Set<string>>(new Set())

  // Resets to fully-selected on every fresh scan — deliberately not
  // persisted, unlike Drive folder mappings.
  useEffect(() => {
    setDeselected(new Set())
  }, [tree])

  const isFileSelected = useCallback((path: string) => !deselected.has(path), [deselected])

  const getGroupState = useCallback((group: LocalFileGroup): GroupSelectionState => {
    const files = flattenFiles(group)
    if (files.length === 0) return 'checked'
    const selectedCount = files.filter(f => !deselected.has(f.path)).length
    if (selectedCount === 0) return 'unchecked'
    if (selectedCount === files.length) return 'checked'
    return 'indeterminate'
  }, [deselected])

  const toggleFile = useCallback((path: string) => {
    setDeselected(prev => {
      const next = new Set(prev)
      if (next.has(path)) next.delete(path); else next.add(path)
      return next
    })
  }, [])

  // Indeterminate or fully-unselected groups select all descendants; a
  // fully-selected group deselects all descendants. Decided from the
  // group's own current state rather than the checkbox's native toggle, so
  // clicking an indeterminate checkbox always selects, never clears.
  const toggleGroup = useCallback((group: LocalFileGroup) => {
    const files = flattenFiles(group)
    setDeselected(prev => {
      const allSelected = files.every(f => !prev.has(f.path))
      const next = new Set(prev)
      for (const f of files) {
        if (allSelected) next.add(f.path); else next.delete(f.path)
      }
      return next
    })
  }, [])

  const selectAll = useCallback(() => setDeselected(new Set()), [])

  const selectNone = useCallback(() => {
    setDeselected(new Set(tree ? flattenFiles(tree).map(f => f.path) : []))
  }, [tree])

  return { isFileSelected, getGroupState, toggleFile, toggleGroup, selectAll, selectNone }
}

import { useState, useEffect } from 'react'
import { LocalFile } from '../types'
import * as pageCache from '../../../lib/pageCache'

export interface PreviewHandle {
  file: LocalFile | null
  page: number
  setFile: (file: LocalFile) => void
  setPage: (page: number) => void
}

// The last previewable file touched by a click — independent of the
// multi-selection (see useSelection): any click on a previewable file
// updates this, whether it's adding or removing that file from the
// selection, while clicking a subfolder or a non-previewable file leaves
// it as whatever was last previewed.
export function usePreview(): PreviewHandle {
  const [file, setFileState] = useState<LocalFile | null>(null)
  const [page, setPage] = useState(1)

  const setFile = (f: LocalFile) => {
    setFileState(f)
    setPage(1)
  }

  useEffect(() => {
    return () => { if (file) pageCache.evict(file.path) }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [file?.path])

  return { file, page, setFile, setPage }
}

import { useState, useCallback, useEffect } from 'react'
import { LocalFileGroup, SelectionItem } from '../types'

function itemKey(item: SelectionItem): string {
  return item.type === 'file' ? `file:${item.path}` : `group:${item.key}`
}

export interface SelectionHandle {
  size: number
  items: SelectionItem[]
  isSelected: (item: SelectionItem) => boolean
  // Plain click: replaces the selection with just this item.
  replace: (item: SelectionItem) => void
  // Cmd/Ctrl-click: adds or removes this item from the existing selection.
  toggle: (item: SelectionItem) => void
}

// The shared multi-selection of files and subfolders driving both row
// highlighting and (Step 3e) batch Drive folder assignment — a single
// selection concept rather than a separate preview-only highlight.
export function useSelection(tree: LocalFileGroup | null): SelectionHandle {
  const [selected, setSelected] = useState<Map<string, SelectionItem>>(new Map())

  // Resets on every fresh scan, like inclusion — a new root's rows aren't
  // the ones that were selected under the old one.
  useEffect(() => {
    setSelected(new Map())
  }, [tree])

  const isSelected = useCallback((item: SelectionItem) => selected.has(itemKey(item)), [selected])

  const replace = useCallback((item: SelectionItem) => {
    setSelected(new Map([[itemKey(item), item]]))
  }, [])

  const toggle = useCallback((item: SelectionItem) => {
    setSelected(prev => {
      const key = itemKey(item)
      const next = new Map(prev)
      if (next.has(key)) next.delete(key); else next.set(key, item)
      return next
    })
  }, [])

  return { size: selected.size, items: Array.from(selected.values()), isSelected, replace, toggle }
}

